import { useDispatch, useSelector } from 'react-redux';
import EditableTable from '../../../features/editable-table/ui/editable-table';
import projectsTableData from '../../../shared/lib/mock-data/projects-table-data.json';
import { isPopupOpen, setPopupClose } from '../../../shared/model/popups-slice';
import Popup from '../../../shared/ui/popup/popup';

const projectsTableColumns = [
  {
    Header: 'Название',
    accessor: 'name',
    changeable: true,
  },
  {
    Header: 'Дата и время изменения',
    accessor: 'date_time',
    changeable: false,
  },
];

function Projects() {
  const dispath = useDispatch();

  const isOpenProjects = useSelector((state) => isPopupOpen(state, 'projects'));

  return (
    <Popup
      isOpened={isOpenProjects}
      title={'Список проектов'}
      onClick={() => dispath(setPopupClose('projects'))}
      tooltipText='Закрыть проекты'>
      <EditableTable
        columns={projectsTableColumns}
        data={projectsTableData}
        onClick={(event) => console.log(event)}
        onSave={(newData) => console.log(newData)}
      />
    </Popup>
  );
}

export default Projects;
