import PropTypes from 'prop-types';
import { useRef } from 'react';
import Draggable from 'react-draggable';
import './widget.scss';

/**
 * React компонент виджета
 * @param {boolean} isOpened - Булев тип, определяющий видимость React компонента;
 * @param {object} style - Объект, стили виджета;
 * @param {string} disableDraggble - Булев тип, отключает перетаскивание;
 */

function Widget({ children, isOpened, style, disableDraggble }) {
  const widgetRef = useRef(null);

  return (
    <Draggable
      handle='.widget__move-handler'
      bounds='.workspace__content'
      defaultPosition={{ x: 12, y: 12 }}
      onStart={() => !disableDraggble}
      nodeRef={widgetRef}>
      <div
        ref={widgetRef}
        style={style}
        className={`widget${isOpened ? ' widget_open' : ''}`}>
        <div
          className={`widget__move-handler widget__move-handler_position_top${disableDraggble ? ' widget__move-handler_inactive' : ''}`}>
          <div className='widget__handler-dot' />
          <div className='widget__handler-dot' />
          <div className='widget__handler-dot' />
        </div>
        <div
          className={`widget__move-handler widget__move-handler_position_bottom${disableDraggble ? ' widget__move-handler_inactive' : ''}`}>
          <div className='widget__handler-dot' />
          <div className='widget__handler-dot' />
          <div className='widget__handler-dot' />
        </div>
        <div className='widget__content'>{children}</div>
      </div>
    </Draggable>
  );
}

Widget.propTypes = {
  isOpened: PropTypes.bool,
  style: PropTypes.object,
  disableDraggble: PropTypes.bool,
};

export default Widget;
