import { createSlice, createSelector } from '@reduxjs/toolkit';

const initialState = {
  popups: [],
};

const popupsSlice = createSlice({
  name: 'popups',
  initialState,
  reducers: {
    setPopupOpen: (store, { payload }) => ({
      popups: [...store.popups, payload],
    }),
    setPopupClose: (store, { payload }) => ({
      popups: store.popups.filter((x) => x !== payload),
    }),
    togglePopupState: (store, { payload }) => {
      const isOpen = store.popups.includes(payload);

      if (!isOpen) {
        return { popups: [payload] };
      }

      return { popups: store.popups.filter((x) => x !== payload) };
    },
  },
});

export const isPopupOpen = createSelector(
  [(state) => state.popups, (_, popupId) => popupId],
  (popups, popupId) => popups.popups.includes(popupId)
);

export const { setPopupOpen, setPopupClose, togglePopupState } =
  popupsSlice.actions;

export default popupsSlice.reducer;
