import PropTypes from 'prop-types';
import './table.scss';
import { useRowSelect, useSortBy, useTable } from 'react-table';
import BoxHeader from '../../../shared/ui/box-header/box-header';
import ArrowDownIcon from '../../assets/icons/arrow-down-icon';

/**
 * React компонент таблицы
 * @param {Array} columns - Массив объектов, параметры столбцов таблицы;
 * @param {Array} data - Массив объектов, данные для таблицы;
 * @param {string} title - Заголовок таблицы;
 */

function Table({ columns, data, title }) {
  const { getTableProps, getTableBodyProps, headerGroups, rows, prepareRow } =
    useTable(
      {
        columns,
        data,
      },
      useSortBy,
      useRowSelect
    );

  return (
    <div className='table'>
      <BoxHeader title={title} type='panel' />
      <table className='table__header-container' {...getTableProps()}>
        <thead>
          {headerGroups.map((headerGroup, rowIndex) => (
            <tr {...headerGroup.getHeaderGroupProps()} key={rowIndex}>
              {headerGroup.headers.map((column) => (
                <th
                  className='table__header'
                  {...column.getHeaderProps(() => {
                    const props = column.getSortByToggleProps();
                    const nextProps = {};
                    for (const key in props) {
                      if (key === 'title') {
                        nextProps[key] = 'Сортировать колонку';
                      } else {
                        nextProps[key] = props[key];
                      }
                    }
                    return nextProps;
                  })}
                  key={column.id}>
                  {column.render('Header')}
                  <span className='table__checkmark'>
                    {column.isSorted ? (
                      column.isSortedDesc ? (
                        <ArrowDownIcon color='var(--black-50)' isInverted />
                      ) : (
                        <ArrowDownIcon
                          color='var(--black-50)'
                          isInverted={false}
                        />
                      )
                    ) : (
                      ''
                    )}
                  </span>
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody className='table__body' {...getTableBodyProps()}>
          {rows.map((row) => {
            prepareRow(row);
            return (
              <tr className='table__row' {...row.getRowProps()} key={row.id}>
                {row.cells.map((cell, cellIndex) => {
                  const cellProps = cell.row.original.getCellProps
                    ? cell.row.original.getCellProps(cell)
                    : cell.getCellProps();

                  return (
                    <td className='table__cell' {...cellProps} key={cellIndex}>
                      {cellProps.children || cell.render('Cell')}
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

Table.propTypes = {
  columns: PropTypes.array.isRequired,
  data: PropTypes.array.isRequired,
  title: PropTypes.string,
  onClick: PropTypes.func,
};

export default Table;
