import PropTypes from 'prop-types';
import { useState, useRef } from 'react';
import './tool-bar.scss';
import { useDispatch, useSelector } from 'react-redux';
import ActionsIcon from '../../../shared/assets/icons/actions-icon';
import CalculatorIcon from '../../../shared/assets/icons/calculator-icon';
import ConstructorIcon from '../../../shared/assets/icons/constructor-icon';
import ExportIcon from '../../../shared/assets/icons/export-icon';
import FileIcon from '../../../shared/assets/icons/file-icon';
import ImportIcon from '../../../shared/assets/icons/import-icon';
import InfoIcon from '../../../shared/assets/icons/info-icon';
import OpenFileIcon from '../../../shared/assets/icons/open-file-icon';
import OutputIcon from '../../../shared/assets/icons/output-icon';
import RedoIcon from '../../../shared/assets/icons/redo-icon';
import RemoveIcon from '../../../shared/assets/icons/remove-icon';
import SaveIcon from '../../../shared/assets/icons/save-icon';
import UndoIcon from '../../../shared/assets/icons/undo-icon';
import projectTitleData from '../../../shared/lib/mock-data/project-title-data.json';
import { togglePopupState } from '../../../shared/model/popups-slice';
import { selectView } from '../../../shared/model/view-slice';
import {
  isWidgetOpen,
  setWidgetOpen,
} from '../../../shared/model/widgets-slice';
import Button from '../../../shared/ui/button/button';
import Divider from './divider/divider';

/**
 * React компонент панели инструментов
 * @param {function} onSave - Коллбэк-функция, вызываемая при нажатии на кнопку "Сохранить";
 * @param {function} excelFile - Коллбэк-функция, вызываемая при импорте excel. Аргументом получает объект excel файла;
 */

function Toolbar({ onSave, excelFile }) {
  const dispatch = useDispatch();
  const isOpenedConstructor = useSelector((state) =>
    isWidgetOpen(state, 'constructor')
  );
  const isOpenedIndications = useSelector((state) =>
    isWidgetOpen(state, 'indications')
  );
  const isOpenedActions = useSelector((state) =>
    isWidgetOpen(state, 'actions')
  );

  const isNotFlowchartView =
    'flowchart' !== useSelector((state) => selectView(state));

  const [isCalculate] = useState(false);

  const openFileInputRef = useRef(null);

  const handleOpenFileClick = () => {
    openFileInputRef.current.click();
  };

  return (
    <section className='tool-bar'>
      <div className='tool-bar__actions-group'>
        <h2 className='tool-bar__project-title'>{projectTitleData.title}</h2>
        <Divider style={{ margin: '0 13px' }} />
        <div className='tool-bar__btns-group'>
          <Button
            text='Создать'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            onClick={() => dispatch(togglePopupState('newProject'))}
            tooltipText='Создать проект'>
            <FileIcon color='var(--element-50)' />
          </Button>
          <Button
            text='Открыть'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            onClick={() => dispatch(togglePopupState('projects'))}
            tooltipText='Открыть проект'>
            <OpenFileIcon color='var(--element-50)' />
          </Button>
          <Button
            text='Очистить'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            onClick={() => dispatch(togglePopupState('confirmation'))}
            tooltipText='Очистить блок схему'>
            <RemoveIcon color='var(--element-50)' />
          </Button>
          <Button
            text='О проекте'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            tooltipText='Изменить информацию о проекте'>
            <InfoIcon color='var(--element-50)' />
          </Button>
          <Divider style={{ margin: '0 13px' }} />
          <Button
            text='Импорт'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            tooltipText='Импортировать данные'
            onClick={handleOpenFileClick}>
            <input
              className='tool-bar__file-input'
              type='file'
              accept='.excel'
              ref={openFileInputRef}
              onChange={(e) => excelFile(e.target.files[0])}
            />
            <ImportIcon color='var(--element-50)' />
          </Button>
          <Button
            text='Экспорт'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            tooltipText='Экспортировать данные'>
            <ExportIcon color='var(--element-50)' />
          </Button>
          <Button
            text='Сохранить'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            onClick={onSave}
            tooltipText='Сохранить в CSV'>
            <SaveIcon width='19px' height='19px' color='var(--element-50)' />
          </Button>
          <Button
            text='Рассчитать'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            isInactive={!isCalculate}
            tooltipText='Рассчитать входные данные'>
            <CalculatorIcon
              color={
                isCalculate ? 'var(--element-50)' : 'var(--element-inactive-75)'
              }
            />
          </Button>
          <Divider style={{ margin: '0 13px' }} />
          <Button
            text='Отмена'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            tooltipText='Отмена действия'>
            <UndoIcon color='var(--element-50)' />
          </Button>
          <Button
            text='Повтор'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            tooltipText='Повтор действия'>
            <RedoIcon color='var(--element-50)' />
          </Button>
          <Divider style={{ margin: '0 13px' }} />
          <Button
            text='Конструктор'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            tooltipText='Открыть конструктор'
            onClick={() => dispatch(setWidgetOpen('constructor'))}
            isInactive={isOpenedConstructor || isNotFlowchartView}>
            <ConstructorIcon
              color={
                isOpenedConstructor || isNotFlowchartView
                  ? 'var(--element-inactive-75)'
                  : 'var(--element-50)'
              }
            />
          </Button>
          <Button
            text='Выходные данные'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            tooltipText='Открыть выходные данные'
            onClick={() => dispatch(setWidgetOpen('indications'))}
            isInactive={isOpenedIndications || isNotFlowchartView}>
            <OutputIcon
              color={
                isOpenedIndications || isNotFlowchartView
                  ? 'var(--element-inactive-75)'
                  : 'var(--element-50)'
              }
            />
          </Button>
          <Button
            text='Действия'
            style={{
              minWidth: '34px',
              minHeight: '33px',
            }}
            tooltipText='Открыть действия'
            onClick={() => dispatch(setWidgetOpen('actions'))}
            isInactive={isOpenedActions || isNotFlowchartView}>
            <ActionsIcon
              color={
                isOpenedActions || isNotFlowchartView
                  ? 'var(--element-inactive-75)'
                  : 'var(--element-50)'
              }
            />
          </Button>
        </div>
      </div>
    </section>
  );
}

Toolbar.propTypes = {
  onSave: PropTypes.func.isRequired,
  excelFile: PropTypes.func.isRequired,
};

export default Toolbar;
