import { configureStore } from '@reduxjs/toolkit';
import popupsSlice from '../../shared/model/popups-slice';
import viewSlice from '../../shared/model/view-slice';
import widgetsSlice from '../../shared/model/widgets-slice';

const store = configureStore({
  reducer: {
    popups: popupsSlice,
    view: viewSlice,
    widgets: widgetsSlice,
  },
});

export default store;
