import PropTypes from 'prop-types';
import { useState, useEffect, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import './workspace.scss';
import { useResizeDetector } from 'react-resize-detector';
import Chart from '../../../../features/chart/ui/chart';
import Flowchart from '../../../../features/flowchart/ui/flowchart';
import IndicatorIcon from '../../../../shared/assets/icons/indicator-icon';
import { BARS_HEIGHT } from '../../../../shared/lib/config/app-config';
import useWindowSize from '../../../../shared/lib/hooks/use-window-size';
import sectionsTableData from '../../../../shared/lib/mock-data/sections-table-data'; // TODO: удалить когда будет API
import { selectView } from '../../../../shared/model/view-slice';
import {
  isWidgetOpen,
  setWidgetOpen,
  setWidgetClose,
} from '../../../../shared/model/widgets-slice';
import Panel from '../../../../shared/ui/panel/panel';
import Table from '../../../../shared/ui/table/table';
import Actions from '../../../../widgets/actions/ui/actions';
import Confirmation from '../../../../widgets/confirmation/ui/confirmation';
import Constructor from '../../../../widgets/constructor/ui/constructor';
import Indications from '../../../../widgets/indications/ui/indications';
import InputData from '../../../../widgets/input-data/ui/input-data';
import NewProject from '../../../../widgets/new-project/ui/new-project';
import Projects from '../../../../widgets/projects/ui/projects';
import View from '../../../../widgets/view/ui/view';

const sectionsTableColumns = [
  {
    Header: 'Участок',
    accessor: 'label',
    Cell: ({ value }) => value,
  },
  {
    Header: 'Температура',
    accessor: 'temp',
    Cell: ({ value }) => (
      <div style={{ display: 'flex', flexDirection: 'row' }}>
        <IndicatorIcon color={value.status_color} />
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {value.meaning}
        </p>
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {'± ' + value.error_margin}
        </p>
      </div>
    ),
  },
  {
    Header: 'Давление',
    accessor: 'pressure',
    Cell: ({ value }) => (
      <div style={{ display: 'flex', flexDirection: 'row' }}>
        <IndicatorIcon color={value.status_color} />
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {value.meaning}
        </p>
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {'± ' + value.error_margin}
        </p>
      </div>
    ),
  },
  {
    Header: 'КННС',
    accessor: 'knns',
    Cell: ({ value }) => (
      <div style={{ display: 'flex', flexDirection: 'row' }}>
        <IndicatorIcon color={value.status_color} />
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {value.meaning}
        </p>
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {'± ' + value.error_margin}
        </p>
      </div>
    ),
  },
  {
    Header: 'Эрозия',
    accessor: 'erosion',
    Cell: ({ value }) => (
      <div style={{ display: 'flex', flexDirection: 'row' }}>
        <IndicatorIcon color={value.status_color} />
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {value.meaning}
        </p>
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {'± ' + value.error_margin}
        </p>
      </div>
    ),
  },
  {
    Header: 'Коррозия',
    accessor: 'corrosion',
    Cell: ({ value }) => (
      <div style={{ display: 'flex', flexDirection: 'row' }}>
        <IndicatorIcon color={value.status_color} />
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {value.meaning}
        </p>
        <p style={{ alignSelf: 'center', margin: '0 0 0 3px' }}>
          {'± ' + value.error_margin}
        </p>
      </div>
    ),
  },
];

/**
 * React компонент рабочего пространства
 * @param {boolean} isSave - Булев тип, определяющий состояние сохранения;
 * @param {function} setIsSave - Коллбэк-функция, вызываемая для сброса сохранения до состояния "false";
 * @param {object} excelFile - Объект с excel;
 */

function Workspace({ isSave, setIsSave, excelFile }) {
  const dispatch = useDispatch();
  const isOpenedConstructor = useSelector((state) =>
    isWidgetOpen(state, 'constructor')
  );
  const isOpenedIndications = useSelector((state) =>
    isWidgetOpen(state, 'indications')
  );
  const isOpenedActions = useSelector((state) =>
    isWidgetOpen(state, 'actions')
  );

  const view = useSelector((state) => selectView(state));

  const [component, setComponent] = useState({});
  const [data, setData] = useState({});
  const [addedNode, setAddedNode] = useState({});
  const [isDelete, setIsDelete] = useState(false);
  const [isValidDelete, setIsValidDelete] = useState(false);
  const [isClean, setIsClean] = useState(false);

  const { height: windowHeight } = useWindowSize();

  const { height: panelsHeight, ref: panelsRef } = useResizeDetector({
    refreshMode: 'debounce',
    refreshRate: 100,
  });

  const contentRef = useRef();

  // Адаптивное изменение размера workspace__content;
  useEffect(() => {
    const compensatedHeight = windowHeight - BARS_HEIGHT;

    if (compensatedHeight < panelsHeight) {
      contentRef.current.style.height = `${panelsHeight}px`;
    } else contentRef.current.style.height = `${compensatedHeight}px`;
  }, [windowHeight, panelsHeight]);

  return (
    <section className='workspace'>
      <div className='workspace__content' ref={contentRef}>
        <Flowchart
          isShow={view === 'flowchart'}
          isSave={isSave}
          setIsSave={setIsSave}
          setComponent={(component) => setComponent(component)}
          nodeData={data}
          setNodeData={(nodeData) => setData(nodeData)}
          setIsOpenedConstructor={(boolean) =>
            boolean
              ? dispatch(setWidgetOpen('constructor'))
              : dispatch(setWidgetClose('constructor'))
          }
          excelFile={excelFile}
          addedNode={addedNode}
          setAddedNode={(params) => setAddedNode(params)}
          isDelete={isDelete}
          setDeleteState={(boolean) => setIsDelete(boolean)}
          isClean={isClean}
          setIsClean={(boolean) => setIsClean(boolean)}
          isValidDelete={isValidDelete}
          setIsValidDelete={(boolean) => setIsValidDelete(boolean)}
        />
        <InputData
          component={component}
          onClose={() => setComponent({})}
          onSave={(data) => setData(data)}
        />
        <Confirmation setIsClean={(boolean) => setIsClean(boolean)} />
        <Projects />
        <NewProject />
      </div>
      <div className='workspace__panels' ref={panelsRef}>
        <div
          className={`workspace__control${view === 'flowchart' ? ' workspace__control_fullscreen' : ''}`}>
          <View />
          <Constructor
            isOpened={isOpenedConstructor && view === 'flowchart'}
            onAddNodes={(node) => setAddedNode(node)}
            onClose={() => dispatch(setWidgetClose('constructor'))}
          />
          <Indications
            isOpened={isOpenedIndications && view === 'flowchart'}
            onClose={() => dispatch(setWidgetClose('indications'))}
          />
          <Actions
            isOpened={isOpenedActions && view === 'flowchart'}
            onDelete={() => setIsDelete(true)}
            onClose={() => dispatch(setWidgetClose('actions'))}
            isValidDelete={isValidDelete}
          />
        </div>
        <Panel isShow={view === 'table'}>
          <Table
            columns={sectionsTableColumns}
            data={sectionsTableData}
            title='Список участков газопровода'
          />
        </Panel>

        <Panel isShow={view === 'chart'}>
          <Chart />
        </Panel>
      </div>
    </section>
  );
}

Workspace.propTypes = {
  isSave: PropTypes.bool.isRequired,
  setIsSave: PropTypes.func.isRequired,
  excelFile: PropTypes.object,
};

export default Workspace;
