import PropTypes from 'prop-types';
import './panel.scss';
import useWindowSize from '../../lib/hooks/use-window-size';
import calculateWidthContainer from '../../lib/utils/calculate-width-container';

/**
 * React компонент панели
 * @param {boolean} isShow - Булев тип, определяющий видимость React компонента;
 */

function Panel({ children, isShow }) {
  const { width } = useWindowSize();

  return (
    <div
      style={{
        width: `${calculateWidthContainer(width, 240, 786)}px`,
      }}
      className={`panel${isShow ? ' panel_show' : ''}`}>
      {children}
    </div>
  );
}

Panel.propTypes = {
  isShow: PropTypes.bool.isRequired,
};

export default Panel;
