import { useEffect, useState } from 'react';
import './chart.scss';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import {
  DATA_CONFIG,
  STATIC_DATA as data,
} from '../../../shared/lib/config/data-config';
import useWindowSize from '../../../shared/lib/hooks/use-window-size';
import calculateWidthContainer from '../../../shared/lib/utils/calculate-width-container';
import ChipsList from '../../../shared/ui/chips-list/chips-list';
import CustomizedAxisTick from './customized-axis-tick/customized-axis-tick';
import CustomizedLabel from './customized-label/customized-label';
import CustomizedTooltip from './customized-tooltip/customized-tooltip';

/**
 * React компонент графика
 */

function Chart() {
  const [view, setView] = useState('temp');

  const selectedUnit = DATA_CONFIG.find((item) => item.id === view);

  const { width: windowWidth } = useWindowSize();

  const legendFormatter = () => {
    return <span className='chart__legend'>{selectedUnit.unit}</span>;
  };

  const isSmallData =
    data.length * 100 < calculateWidthContainer(windowWidth, 531, 757);

  let width = isSmallData
    ? calculateWidthContainer(windowWidth, 531, 757)
    : data.length * 100;

  useEffect(() => {
    if (isSmallData) {
      const yAxisElement = document.querySelector(
        '.recharts-layer.recharts-cartesian-axis.recharts-yAxis.yAxis'
      );

      if (yAxisElement) {
        yAxisElement.style.transform = 'translateX(0px)';
      }
    }
  }, [isSmallData]);

  return (
    <>
      <div className='chart__menu'>
        <ChipsList
          chips={DATA_CONFIG.map((i) => {
            return { ...i, isDisabled: view === i.label };
          })}
          textSize='large'
          value={view}
          onChange={(chips) => setView(chips)}
        />
      </div>
      <div
        className={`chart__wrapper ${isSmallData ? '' : 'chart__wrapper_active-scrollbar'}`}
        onScroll={(e) => {
          let wrapper = document.querySelector(
            '.chart__wrapper_active-scrollbar .recharts-surface'
          );
          let chartWrapper = document.querySelector(
            '.chart__wrapper_active-scrollbar .chart__wrapper'
          );

          const allAxis = document.querySelectorAll(
            '.chart__wrapper_active-scrollbar .recharts-yAxis'
          );

          allAxis?.forEach((axis) => {
            const orientation = axis
              .querySelector(
                '.chart__wrapper_active-scrollbar .recharts-cartesian-axis-tick-line'
              )
              ?.getAttribute('orientation');

            const position =
              orientation === 'left'
                ? e.target.scrollLeft
                : e.target.scrollLeft -
                  wrapper?.clientWidth +
                  chartWrapper?.clientWidth;

            axis.style = 'transform: translateX(' + position + 'px);';
          });
        }}>
        <AreaChart width={width} height={300} data={data}>
          <defs>
            <linearGradient
              id={`color${selectedUnit.id}`}
              x1='0'
              y1='0'
              x2='0'
              y2='1'>
              <stop
                offset='5%'
                stopColor={selectedUnit.color}
                stopOpacity={0.8}
              />
              <stop
                offset='95%'
                stopColor={selectedUnit.color}
                stopOpacity={0}
              />
            </linearGradient>
          </defs>
          <CartesianGrid stroke='var(--chart)' strokeDasharray='3 3' />
          <XAxis
            stroke='var(--chart)'
            dataKey='id'
            label={
              <CustomizedLabel
                viewBox={{ x: 0, y: 0, width: width, height: 400 }}
              />
            }
            tick={CustomizedAxisTick}
            height={50}
          />
          <Tooltip
            isAnimationActive={false}
            content={<CustomizedTooltip selectedUnit={selectedUnit} />}
          />
          <Legend
            wrapperStyle={{ marginLeft: '16px' }}
            formatter={legendFormatter}
            align='left'
            verticalAlign='top'
            height={36}
          />
          <Area
            type='monotone'
            dataKey={selectedUnit.id}
            stroke={selectedUnit.color}
            fillOpacity={1}
            fill={`url(#color${selectedUnit.id})`}
          />
          <YAxis
            stroke='var(--chart)'
            type='number'
            tick={CustomizedAxisTick}
          />
        </AreaChart>
      </div>
    </>
  );
}

export default Chart;
