import PropTypes from 'prop-types';
import { useState } from 'react';
import CheckIcon from '../../../shared/assets/icons/check-icon';
import EditIcon from '../../../shared/assets/icons/edit-icon';
import ReturnIcon from '../../../shared/assets/icons/return-icon';
import Button from '../../../shared/ui/button/button';
import Table from '../../../shared/ui/table/table';
import './editable-table.scss';

/**
 * React компонент таблицы с возможностью редактирования строк
 * @param {object} columns - Массив объектов, параметры столбцов таблицы;
 * @param {object} data - Массив объектов, данные для таблицы;
 * @param {string} title - Заголовок таблицы;
 * @param {function} onClick - Коллбэк-функция, вызываемая при клике на кнопку: "Открыть проект";
 * @param {function} onSave - Коллбэк-функция, вызываемая при сохранении изменений в строке;
 */

const EditableTable = ({ columns, data, title, onClick, onSave }) => {
  const [initialData, setInitialData] = useState(data);
  const [editingRow, setEditingRow] = useState(null);
  const [editedData, setEditedData] = useState({});

  const handleEdit = (rowIndex) => {
    setEditingRow(rowIndex);
    setEditedData(initialData[rowIndex]);
  };

  const handleSave = (rowIndex) => {
    const newData = [...initialData];
    newData[rowIndex] = editedData;
    setInitialData(newData);
    setEditingRow(null);
    onSave(newData);
  };

  const handleChange = (rowIndex, columnId, value) => {
    setEditedData((prev) => ({
      ...prev,
      [columnId]: value,
    }));
  };

  const enhancedColumns = [
    ...columns,
    {
      Header: 'Действия',
      accessor: 'actions',
      id: 'actions',
      disableSortBy: true,
      changeable: false,
      Cell: ({ row }) => (
        <div className='editable-table__actions'>
          {editingRow === row.index ? (
            <Button
              tooltipText='Сохранить'
              onClick={() => handleSave(row.index)}>
              <CheckIcon color='var(--element-50)' />
            </Button>
          ) : (
            <Button
              tooltipText='Редактировать'
              onClick={() => handleEdit(row.index)}>
              <EditIcon color='var(--element-50)' />
            </Button>
          )}
          <Button tooltipText='Открыть проект' onClick={() => onClick(row)}>
            <ReturnIcon color='var(--element-50)' />
          </Button>
        </div>
      ),
    },
  ];

  const enhancedData = initialData.map((row, index) => ({
    ...row,
    original: row,
    getCellProps: (cell) => {
      const isEditable = cell.column.changeable && editingRow === index;
      const isActionColumn = cell.column.id === 'actions';

      return {
        ...cell.getCellProps(),
        children:
          isEditable && !isActionColumn ? (
            <input
              value={editedData[cell.column.id] || ''}
              onChange={(e) =>
                handleChange(index, cell.column.id, e.target.value)
              }
              className='editable-table__input'
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleSave(index)}
            />
          ) : (
            cell.render('Cell')
          ),
      };
    },
  }));

  return <Table columns={enhancedColumns} data={enhancedData} title={title} />;
};

EditableTable.propTypes = {
  columns: PropTypes.array.isRequired,
  data: PropTypes.array.isRequired,
  title: PropTypes.string,
  onClick: PropTypes.func.isRequired,
  onSave: PropTypes.func.isRequired,
};

export default EditableTable;
