import { useDispatch, useSelector } from 'react-redux';
import { isPopupOpen, setPopupClose } from '../../../shared/model/popups-slice';
import FormBuilder from '../../../shared/ui/form-builder/form-builder';
import Popup from '../../../shared/ui/popup/popup';

const params = [
  {
    id: 0,
    label: 'Название проекта',
    placeholder: 'Название',
  },
];

function NewProject() {
  const dispath = useDispatch();

  const isOpenProjects = useSelector((state) =>
    isPopupOpen(state, 'newProject')
  );

  return (
    <Popup
      isOpened={isOpenProjects}
      title={'Создать новый проект'}
      onClick={() => dispath(setPopupClose('newProject'))}
      tooltipText='Закрыть создание проекта'>
      <FormBuilder params={params} />
    </Popup>
  );
}

export default NewProject;
