const CustomizedLabel = ({ viewBox }) => {
  const { x, y, width, height } = viewBox;
  const midX = width / 2;
  const midY = height / 2;
  const text = 'Участки';
  const fontSize = 14;
  const padding = 10;

  // Вычисления ширины и длины прямоугольника для фона текста
  const textWidth = text.length * (fontSize / 2);
  const rectWidth = textWidth + 2 * padding;
  const rectHeight = fontSize + 2;

  return (
    <svg x={x} y={y} width={width} height={height}>
      <path
        d={`M ${0} ${midY} Q ${midX} ${midY + 40} ${width} ${midY}`}
        stroke='var(--chart)'
        fill='none'
      />
      <rect
        x={midX - rectWidth / 2}
        y={midY - rectHeight / 2 + 20}
        width={rectWidth}
        height={rectHeight}
        fill='white'
      />
      <text
        x={midX}
        y={midY + 20}
        textAnchor='middle'
        fill='var(--chart)'
        dominantBaseline='middle'
        fontSize={fontSize}>
        {text}
      </text>
    </svg>
  );
};

export default CustomizedLabel;
