import PropTypes from 'prop-types';
import { useEffect, createRef } from 'react';
import './popup.scss';
import CrossIcon from '../../assets/icons/cross-icon';
import BoxHeader from '../box-header/box-header';
import Button from '../button/button';

/**
 * React компонент модального окна
 * @param {boolean} isOpened - Булев тип, определяющий видимость модального окна;
 * @param {string} title - Строка, заголовок модального окна;
 * @param {function} onClick - Коллбэк-функция, вызываемая при закрытии модального окна;
 * @param {string} tooltipText - Строка, текст всплывающей подсказки для кнопки закрытия;
 * @param {object} style - Объект, стили модального окна;
 */

function Popup({ children, isOpened, title, onClick, tooltipText, style }) {
  const popupRef = createRef();

  useEffect(() => {
    const closeByEscape = (e) => {
      if (e.key === 'Escape') {
        onClick();
      }
    };

    document.addEventListener('keydown', closeByEscape);
    return () => document.removeEventListener('keydown', closeByEscape);
  }, [isOpened, onClick]);

  useEffect(() => {
    const handleFocus = (e) => {
      if (popupRef.current && !popupRef.current.contains(e.relatedTarget)) {
        popupRef.current.focus();
      }
    };

    if (isOpened) {
      document.addEventListener('focusout', handleFocus);
    }
    return () => document.removeEventListener('focusout', handleFocus);
  }, [isOpened, onClick, popupRef]);

  useEffect(() => {
    if (isOpened) {
      document.body.style.overflow = 'hidden';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpened]);

  const handleOverlay = (e) => {
    if (e.target === e.currentTarget) {
      onClick();
    }
  };

  return (
    <div
      data-testid='popup'
      className={isOpened ? 'popup popup_open' : 'popup'}
      role='button'
      tabIndex={0}
      onMouseDown={handleOverlay}
      ref={popupRef}>
      <div style={style} className='popup__content'>
        <BoxHeader title={title} type='popup'>
          <Button
            style={{
              minWidth: '10px',
              minHeight: '10px',
            }}
            onClick={onClick}
            tooltipText={tooltipText}>
            <CrossIcon color='var(--text)' />
          </Button>
        </BoxHeader>
        {children}
      </div>
    </div>
  );
}

Popup.propTypes = {
  isOpened: PropTypes.bool.isRequired,
  title: PropTypes.string,
  onClick: PropTypes.func.isRequired,
  tooltipText: PropTypes.string.isRequired,
  style: PropTypes.object,
};

export default Popup;
