import { createSlice, createSelector } from '@reduxjs/toolkit';

const initialState = {
  widgets: ['constructor', 'indications', 'actions'],
};

const widgetsSlice = createSlice({
  name: 'widgets',
  initialState,
  reducers: {
    setWidgetOpen: (store, { payload }) => ({
      widgets: [...store.widgets, payload],
    }),
    setWidgetClose: (store, { payload }) => ({
      widgets: store.widgets.filter((x) => x !== payload),
    }),
  },
});

export const isWidgetOpen = createSelector(
  [(state) => state.widgets, (_, widgetId) => widgetId],
  (widgets, widgetId) => widgets.widgets.includes(widgetId)
);

export const { setWidgetOpen, setWidgetClose } = widgetsSlice.actions;

export default widgetsSlice.reducer;
