import PropTypes from 'prop-types';
import CrossIcon from '../../../shared/assets/icons/cross-icon';
import statusData from '../../../shared/lib/mock-data/status-data.json';
import valueData from '../../../shared/lib/mock-data/value-data.json';
import BoxHeader from '../../../shared/ui/box-header/box-header';
import Button from '../../../shared/ui/button/button';
import Status from '../../../shared/ui/status/status';
import Value from '../../../shared/ui/value/value';
import Widget from '../../../shared/ui/widget/widget';

/**
 * React компонент индикации выходных данных
 * @param {boolean} isOpened - Булев тип, определяющий видимость React компонента;
 * @param {function} onClose - Коллбэк-функция, вызываемая при нажатии на кнопку "Закрыть";
 */

function Indications({ isOpened, onClose }) {
  return (
    <Widget
      isOpened={isOpened}
      style={{
        position: 'absolute',
        top: 0,
        left: '237px',
        minWidth: '225px',
        width: 'min-content',
      }}>
      <BoxHeader title={`Выходные данные:`} type='panel'>
        <Button
          style={{
            minWidth: '10px',
            minHeight: '10px',
          }}
          onClick={onClose}
          tooltipText='Закрыть выходные данные'>
          <CrossIcon color='var(--text)' />
        </Button>
      </BoxHeader>
      <Status
        color={statusData.color}
        percent={statusData.condition}
        label={statusData.label}
        description={statusData.description}
      />
      {valueData.map(
        ({
          id,
          title,
          description,
          unit,
          meaning,
          icon_src,
          error_margin,
          status_color,
        }) => (
          <Value
            key={id}
            title={title}
            description={description}
            unit={unit}
            meaning={meaning}
            iconSrc={icon_src}
            errorMargin={error_margin}
            statusColor={status_color}
          />
        )
      )}
    </Widget>
  );
}

Indications.propTypes = {
  isOpened: PropTypes.bool.isRequired,
  onClose: PropTypes.func.isRequired,
};

export default Indications;
