import PropTypes from 'prop-types';
import './customized-tooltip.scss';

/**
 * React компонент всплывающей подсказки графиков
 */

function CustomizedTooltip({ active, payload, selectedUnit }) {
  if (active && payload?.length) {
    return (
      <div className='customized-tooltip'>
        <p className='customized-tooltip__text'>{`${payload[0].value} ${selectedUnit.unit}`}</p>
      </div>
    );
  }
  return null;
}

CustomizedTooltip.propTypes = {
  active: PropTypes.any,
  payload: PropTypes.any,
  selectedUnit: PropTypes.any,
};

export default CustomizedTooltip;
