import PropTypes from 'prop-types';
import './custom-output.scss';
import { memo } from 'react';
import { Handle, Position, useEdges } from 'reactflow';
import { BASE_URL } from '../../../../shared/lib/config/api-config';

const MODE = process.env.REACT_APP_MODE;

const CustomOutput = memo(({ id, data, selected }) => {
  const relativePathToImage = `static/${data.type}_in_node.svg`;

  const edges = useEdges();

  const isTargetConnected = edges.some((i) => i.target === id);

  return (
    <div
      title='Вход'
      className={`custom-input${selected ? ' custom-input_selected' : ''}`}>
      <Handle
        isConnectable={true}
        className={`custom-output__handle-left${
          isTargetConnected
            ? selected
              ? ' custom-output__handle-left_connected custom-output__handle-left_selected'
              : ' custom-output__handle-left_connected'
            : selected
              ? ' custom-output__handle-left_selected'
              : ''
        }`}
        type='target'
        position={Position.Left}
      />
      <div className='custom-output__content'>
        <p className='custom-output__label'>{data.label}</p>
        <img
          className='custom-output__icon'
          src={
            MODE === 'production'
              ? `${BASE_URL}${relativePathToImage}`
              : require(`../../../../${relativePathToImage}`)
          }
          alt='Иконка узла'
        />
      </div>
    </div>
  );
});

CustomOutput.displayName = 'CustomOutput';

CustomOutput.propTypes = {
  id: PropTypes.string.isRequired,
  data: PropTypes.object.isRequired,
  selected: PropTypes.bool.isRequired,
};

export default CustomOutput;
